// Original instructional practice form, reviewed against May 2027 format.
// No released College Board questions or passages are reproduced.
const periods=['1491–1607','1607–1754','1754–1800','1800–1848','1844–1877','1865–1898','1890–1945','1945–1980','1980–Present'];
const domain=(u:number)=>`APUSH: ${periods[u-1]}`;
const links={exam:'https://apcentral.collegeboard.org/courses/ap-united-states-history/exam',updates:'https://apcentral.collegeboard.org/courses/ap-history-exam-updates',declaration:'https://www.archives.gov/founding-docs/declaration-transcript',constitution:'https://www.archives.gov/founding-docs/constitution-transcript',amendments:'https://www.archives.gov/founding-docs/amendments-11-27',erie:'https://eriecanalway.org/learn/history-culture/fast-facts',monroe:'https://www.archives.gov/milestone-documents/monroe-doctrine',emancipation:'https://www.archives.gov/milestone-documents/emancipation-proclamation',dawes:'https://www.archives.gov/milestone-documents/dawes-act',socialSecurity:'https://www.archives.gov/milestone-documents/social-security-act',eo8802:'https://www.archives.gov/milestone-documents/executive-order-8802',eo9066:'https://www.archives.gov/milestone-documents/executive-order-9066',truman:'https://www.archives.gov/milestone-documents/truman-doctrine',civilRights:'https://www.archives.gov/milestone-documents/civil-rights-act',votingRights:'https://www.archives.gov/milestone-documents/voting-rights-act',plessy:'https://www.archives.gov/milestone-documents/plessy-v-ferguson',wells:'https://www.gutenberg.org/cache/epub/14975/pg14975-images.html',johnson:'https://www.archives.gov/legislative/features/voting-rights-1965/johnson.html'};
const mcq:any[]=[];
const positions=Array.from({length:55},(_,i)=>i%4);let seed=741;
for(let i=positions.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;let j=seed%(i+1);[positions[i],positions[j]]=[positions[j],positions[i]];}
function set(unit:number,id:string,passage:string,stimulus?:any){return{unit,id:`apush-exam-stimulus-${id}`,passage,stimulus};}
function q(s:any,question:string,right:string,wrong:string[],why:string,errors:string[],difficulty='Hard'){
 const answer=positions[mcq.length],choices=[...wrong],reasons=[...errors];choices.splice(answer,0,right);reasons.splice(answer,0,why);
 mcq.push({id:`apush-exam-mcq-${String(mcq.length+1).padStart(2,'0')}`,domain:domain(s.unit),difficulty,format:'mcq',question,choices,answer,explanation:reasons.map((r,i)=>`“${choices[i]}”: ${r}`).join('\n'),passage:s.passage,stimulusId:s.id,...(s.stimulus?{stimulus:s.stimulus}:{})});
}
const s1=set(1,'01',`Original secondary interpretation written for this practice form, not a quotation from a published historian:\n\nA continent-wide description of Native North America can obscure the institutions it seeks to explain. Communities using irrigation in the Southwest and communities drawing on Northwest Coast fisheries both organized dependable food supplies, but they did not organize production in identical ways. Maize cultivation, hunting, trade, and political alliance varied across regions and over time. European newcomers entered territories already shaped by human decisions about settlement, cultivation, burning, and exchange. An environment created opportunities and constraints; it did not issue a single instruction that every community followed.`);
q(s1,'Which additional finding would most directly strengthen the interpretation’s final claim?','Evidence that neighboring communities sharing a climate adopted different land-use practices.', ['A catalog showing that both regions experienced seasonal changes.','A European map placing both regions within a claimed empire.','A comparison showing different ocean temperatures on the two coasts.'],'Different choices under similar conditions demonstrate that environment did not uniquely determine practice.',['Seasonality alone does not distinguish environmental constraints from human choices.','An imperial claim reveals European intentions, not Indigenous land use.','Different temperatures show environmental variation but do not test the argument about choices.']);
q(s1,'The interpretation most directly challenges which approach to precontact societies?','Using a single later image of Plains life as a model for the entire continent.', ['Examining how agricultural exchange affected population density.','Comparing political alliances across distinct Indigenous nations.','Investigating how controlled burning altered local ecosystems.'],'A uniform later stereotype conceals the regional and temporal diversity emphasized by the passage.',['Exchange and population are compatible with the analysis.','Comparing distinct nations respects the passage’s diversity.','Environmental modification supports the interpretation.']);
q(s1,'Which development after 1492 most clearly illustrates the passage’s interaction between external conditions and human adaptation?','Some Indigenous communities incorporated introduced horses into changing transport and hunting systems.', ['European legal claims immediately erased Indigenous diplomatic institutions.','Maize first reached every part of North America through Spanish missions.','Colonial settlements expanded only where precontact farming had been absent.'],'An introduced animal changed opportunities, while communities adapted it in varying ways.',['Indigenous diplomacy continued despite colonial claims.','Maize had spread across the Americas before European colonization.','Colonization often displaced or used existing agricultural landscapes.']);
const s2=set(2,'02',`Original comparative interpretation, not an archival quotation:\n\nIn the Chesapeake, tobacco exports encouraged employers to seek labor and land. Early reliance on contracted servants gave way over time to a larger system of hereditary racial enslavement supported by colonial law. Meanwhile, merchants in northern ports sold food and shipping services to plantation regions. The resulting system was neither a collection of sealed regional economies nor a uniform labor market. Legal status, length of obligation, household composition, and the possibility of mobility differed sharply among workers even when their products entered connected trade networks.`);
q(s2,'Which evidence would best substantiate the passage’s claim that law helped transform labor relations?','A statute making a child’s enslaved status follow that of the mother.', ['A merchant’s account listing barrels of tobacco shipped in one season.','A navigation chart showing a route from Boston to Barbados.','A deed transferring a mill from one freeholder to another.'],'Maternal inheritance made bondage reproducible across generations and protected slaveholders’ claims.',['Export volume does not by itself identify the legal transformation.','A route supports economic connection but not hereditary status.','A property sale does not establish the described change in labor law.']);
q(s2,'Which interpretation of northern trade is best supported by the passage?','A region could profit from plantation slavery without reproducing the plantation region’s predominant production system.', ['Northern merchants relied on a self-contained economy largely separated from Atlantic coercion.','The legal status of a northern sailor was determined by the enslaved status of Caribbean field laborers.','The expansion of interregional commerce made regional economic differences less consequential than before.'],'Interdependence connects different regional systems without making their labor relations identical.',['Provisioning and shipping establish Atlantic connections.','Commercial connection did not transfer another worker’s legal status.','The passage stresses continuing consequential differences, not their disappearance.']);
q(s2,'Which comparison would most effectively test the passage’s distinction between legal status and market participation?','Compare a servant’s fixed-term contract with laws restricting an enslaved worker whose crop entered the same export trade.', ['Compare two tobacco prices without considering the workers who produced the crop.','Compare English and Spanish royal portraits displayed in colonial offices.','Compare ocean crossing times on ships with similar routes and cargoes.'],'The proposed comparison holds market connection in view while examining the legal difference.',['Prices alone cannot establish workers’ legal rights or obligations.','Royal imagery might reveal imperial legitimacy but not this distinction.','Travel times do not directly test labor status.']);
const s3=set(3,'03',`Primary-source instructional paraphrase, not a quotation: Continental Congress, Declaration of Independence, 1776. The document presents government as legitimate when it protects inherent rights and rests on the consent of the governed. It justifies changing an abusive government and accompanies these principles with specific charges against the British king. The argument was addressed both to the colonists and to a wider international audience.\nPrimary text: ${links.declaration}`);
q(s3,'Why would the international audience matter to interpreting the document’s presentation of colonial grievances?','The authors sought to make separation appear legitimate to potential foreign supporters.', ['The authors were requesting representation in a functioning international legislature.','The authors expected European monarchs to recognize an immediate end to slavery in America.','The authors were explaining why colonial assemblies had already become sovereign European states.'],'A justification addressed beyond Britain could support diplomatic recognition and assistance.',['No such international legislature governed the imperial dispute.','The document did not abolish slavery.','The colonies claimed independence, not conversion into European states.']);
q(s3,'Which development best explains why these principles became a justification for separation rather than merely reform within the empire?','Repeated conflicts over imperial authority weakened prospects for a settlement colonists would accept.', ['The removal of every imperial trade restriction before 1763.','The establishment of universal male suffrage across the colonies in 1765.','A British guarantee that colonial assemblies could veto parliamentary legislation.'],'Escalating disputes helped transform demands for rights within empire into a case for independence.',['Britain retained and enforced imperial regulations.','Universal male suffrage had not been established.','Such a guarantee would have reduced the central constitutional dispute.']);
q(s3,'Which subsequent use of the document’s language most clearly illustrates an effect beyond its authors’ immediate political aim?','Excluded groups invoked its principles to challenge restrictions maintained after independence.', ['Federal officials treated its grievances as a complete code of criminal law.','The Articles of Confederation required every state to abolish slavery on ratification.','British officials accepted that every imperial dependency was thereby independent.'],'Universal claims could support later equality demands not fulfilled by independence itself.',['The Declaration was not a criminal code.','The Articles did not require national abolition.','The Declaration did not free every British dependency.']);
q(s3,'Which evidence would best qualify a claim that independence immediately placed government on an equal basis of consent?','Continued political exclusion and enslavement within the new states.', ['The presence of written arguments against British authority.','The use of print networks to communicate colonial protests.','The formation of diplomatic ties with France.'],'Restricted participation and slavery reveal limits to the application of consent.',['Arguments for separation do not establish who actually participated.','Print circulation can broaden mobilization without ensuring equality.','An alliance concerns external relations rather than equal domestic consent.']);
const s4=set(3,'04',`Primary-source instructional paraphrase, not a quotation: U.S. Constitution, Article I, 1787. Congress receives authority to raise revenue, regulate commerce among states and with foreign nations, and make laws necessary and proper for carrying out enumerated responsibilities. Other provisions distribute legislative representation between a population-based House and a Senate with equal state representation.\nPrimary text: ${links.constitution}`);
q(s4,'Which problem under the Confederation would these revenue and commerce powers most directly address?','Dependence on state cooperation to fund national obligations and coordinate economic policy.', ['The absence of any state-level political institutions after independence.','A requirement that federal judges approve every local property transfer.','The lack of a national government capable of conducting diplomacy under any circumstances.'],'The new powers strengthened national capacity where requisitions and fragmented authority had limited it.',['State institutions were powerful, not absent.','That was not a defining Confederation requirement.','The Confederation could conduct diplomacy despite its weaknesses.']);
q(s4,'A critic worries that the necessary-and-proper clause will concentrate authority far from local voters. This concern most closely resembles','Anti-Federalist arguments about insufficient constraints on the proposed national government.', ['Federalist support for a national system capable of managing faction.','Hamilton’s defense of implied powers in support of a national bank.','Washington’s argument that the United States should avoid permanent foreign alliances.'],'The worry centers on distant power and accountability, common Anti-Federalist objections.',['Federalists generally defended the proposed structure against this objection.','Hamilton used implied powers to justify national action rather than this warning.','Foreign alliances were not the clause’s central issue.']);
q(s4,'Which early policy dispute best demonstrates that these provisions did not settle the practical boundaries of national power?','The disagreement over whether Congress could charter a national bank.', ['The disagreement over the founding date of Jamestown.','The division between British and French forces during the Seven Years’ War.','The contest over Spanish conversion policy in the Pueblo Revolt.'],'The bank required competing interpretations of enumerated and implied powers.',['Jamestown’s chronology was not a federal-powers dispute.','The imperial war preceded this constitutional framework.','The revolt concerned Spanish rule rather than U.S. congressional authority.']);
const canalMap={type:'map',title:'Schematic water connection after the Erie Canal opened, 1825',regions:[{id:'buffalo',label:'Buffalo / Lake Erie',x:8,y:42},{id:'rochester',label:'Rochester',x:31,y:24},{id:'albany',label:'Albany / Hudson',x:74,y:32},{id:'nyc',label:'New York City / Atlantic',x:88,y:84}],connections:[{from:'buffalo',to:'rochester',label:'Erie Canal'},{from:'rochester',to:'albany',label:'Erie Canal'},{from:'albany',to:'nyc',label:'Hudson River'}],note:'Original instructional schematic; not to scale, not a complete canal route, and not an archival map. Points indicate connections rather than precise geography. Historical route reference: '+links.erie};
const s5=set(4,'05',`Use the original schematic showing connections between Lake Erie, the canal, the Hudson River, and New York City's Atlantic port after 1825. It depicts a transport network, not measurements of actual freight or population. The Erie Canal connected the Buffalo and Albany areas; travel onward to New York City used the Hudson. Source for the underlying route: ${links.erie}`,canalMap);
q(s5,'Which economic development would the network most directly encourage?','Interior producers could reach Atlantic markets through a linked inland-water route.', ['Plantation production could shift to an exclusively Pacific export network.','New York’s coastal trade could operate without connections to inland producers.','Western farmers would face a legal prohibition on selling products locally.'],'The mapped connections reduced barriers between inland production and an Atlantic port.',['The map does not show a Pacific route.','Its significance is precisely the inland-coastal link.','A transport network does not itself impose such a sales prohibition.']);
q(s5,'Which evidence would be most necessary before concluding from this map that the canal increased one city’s population?','Comparable population records and evidence connecting migration or employment to canal activity.', ['A larger drawing of the same schematic with more prominent arrows.','A list of congressional representatives from states without canal connections.','A map locating mountains but containing no demographic information.'],'A causal demographic claim requires more than knowledge that a connection existed.',['Graphic emphasis adds no demographic evidence.','Representatives elsewhere do not test the claimed city growth.','Terrain may explain routes but cannot establish population change.']);
q(s5,'Which group would most likely favor public investment in this type of improvement, while differing from strict opponents of federal economic activism?','Advocates of the American System who emphasized transportation and national market development.', ['Nullifiers seeking state power to invalidate every federal tariff.','Immediate abolitionists whose principal program concerned emancipation.','Colonization advocates whose principal program concerned resettlement abroad.'],'Internal improvements were central to the American System’s economic vision.',['Nullification addressed a different constitutional claim and was not this development program.','Abolition’s primary demand does not identify the transport-investment position.','Colonization does not explain the network-building program.']);
q(s5,'Which interpretation best places this network within the Market Revolution?','New infrastructure could change specialization and commercial dependence without making gains equal across households.', ['The map establishes that transport change removed farmers from price fluctuations.','Canal construction demonstrates that agricultural exports declined whenever cities grew.','The route proves that all workers along it controlled the businesses employing them.'],'Market access could increase opportunity and exposure to markets, with uneven effects.',['Greater commercial integration could increase exposure to price changes.','Urban growth and agricultural trade could reinforce each other.','Connections do not establish workers’ ownership or bargaining power.']);
const s6=set(4,'06',`Primary-source instructional paraphrase, not a quotation: President James Monroe's annual message to Congress, 1823. Monroe opposes new European colonization in the Americas and warns against extending European political systems into the hemisphere, while distinguishing these concerns from existing European colonies and from Europe's internal affairs. This is a statement of policy, not evidence that the United States already possessed the capacity to enforce it everywhere.\nPrimary text: ${links.monroe}`);
q(s6,'Which context best helps explain the policy’s formulation?','Independence movements in Latin America and concern about renewed European intervention.', ['The dissolution of NATO after the Korean War.','A congressional decision to join the League of Nations.','The immediate aftermath of U.S. annexation of the Philippines.'],'New states and the possibility of European restoration shaped the hemispheric warning.',['NATO and Korea belong to a later period.','The League belongs to the post-World War I debate, and the U.S. did not join.','Philippine annexation came decades after 1823.']);
q(s6,'Which inference most carefully distinguishes policy goals from practical power?','The message asserted a hemispheric position whose enforcement depended on circumstances and resources.', ['The announcement alone transferred sovereignty over Latin America to Washington.','Existing European colonies immediately ceased to exist under the policy.','The policy’s statement guaranteed that Latin American governments accepted U.S. leadership.'],'A proclaimed doctrine is evidence of intent, not automatic control or consent.',['A declaration did not create such a legal transfer.','The message distinguished existing colonies from new colonization.','Governments’ responses require separate evidence.']);
q(s6,'A historian compares this message with later justifications for U.S. intervention in the Caribbean. What is the strongest analytical approach?','Examine how later leaders adapted an earlier claim while changing its scope and means of enforcement.', ['Treat later intervention as proof that every element of the 1823 policy had the same meaning in all periods.','Assume the original message had no relationship to subsequent foreign-policy arguments.','Classify both policies as an unchanging refusal to participate in international affairs.'],'Continuity in cited principles can coexist with changes in power and practice.',['Historical reuse does not establish identical meaning.','Later invocations make the relationship worth examining.','Hemispheric warnings and interventions are forms of international engagement.']);
const s7=set(5,'07',`Original secondary interpretation written for this form:\n\nTerritorial controversy before the Civil War was not merely a dispute over where settlers could move. Admitting a state altered the distribution of political power, while rules governing a territory could shape the expansion of enslaved labor and the future value of slaveholders' claims. Compromise repeatedly deferred conflict but also created new enforcement disputes. A policy advertised as allowing settlers to decide could intensify disagreement when rival groups disputed who qualified to participate and whether the process itself was legitimate.`);
q(s7,'Which development most directly exemplifies the final sentence?','Competing proslavery and antislavery governments and violence in Kansas.', ['California’s admission under a settlement negotiated in Congress.','The executive negotiation of the boundary settlement with Britain in Oregon.','The acquisition of Mexican territory through a peace treaty.'],'Kansas exposed conflict over settlers, elections, and the legitimacy of popular sovereignty.',['California’s admission illustrates congressional compromise, not the rival territorial voting process described.','The Oregon boundary concerned diplomacy rather than rival slavery governments.','The treaty created the territorial question but not this mechanism for deciding it.']);
q(s7,'Which evidence best supports the argument that compromise could create new enforcement conflict?','Northern resistance to federal requirements for returning alleged fugitives under the 1850 law.', ['The use of equal Senate representation in the constitutional design of 1787.','The absence of slavery from territorial debates following the Mexican cession.','Agreement by abolitionists and slaveholders that federal enforcement should remain unchanged.'],'The strengthened Fugitive Slave Act carried slavery’s enforcement into northern communities.',['Senate design explains political stakes but not the new 1850 enforcement disputes.','Slavery was central to those territorial debates.','The opposing groups sharply contested enforcement.']);
q(s7,'Which qualification would most strengthen rather than abandon the interpretation?','Local political disputes operated within a wider struggle over slavery’s future, not simply competition among settlers.', ['Territorial governments became the exclusive cause of the Civil War, replacing disputes over slavery.','Economic interests can be ignored because participants used constitutional language.','Compromise proposals prevented territorial controversies from influencing national parties.'],'A layered explanation links local mechanisms with the central national institution being contested.',['That removes the institutional conflict underlying the passage.','Constitutional and economic arguments were intertwined.','The controversies contributed to party realignment and collapse.']);
const s8=set(5,'08',`Primary-source instructional paraphrase, not a quotation: Abraham Lincoln, Emancipation Proclamation, January 1, 1863. Acting as commander in chief during rebellion, Lincoln declares people held in slavery in specified rebellious areas free and commits the executive and military to recognizing that freedom. The order also provides for accepting eligible Black men into U.S. armed service. Its geographic exclusions and wartime basis matter to interpreting its reach.\nPrimary text: ${links.emancipation}`);
q(s8,'Which conclusion best follows from the Proclamation’s geographic limits?','The order connected emancipation to military authority and did not by itself establish abolition in every jurisdiction.', ['The order left Union military policy toward slavery entirely unchanged.','The order depended on Confederate legislatures voluntarily amending their constitutions.','The order applied only to loyal border states because federal officials controlled them.'],'Its wartime and territorial scope explains both its importance and its limits.',['It fundamentally altered Union policy and war aims.','Recognition and enforcement rested on Union authority and military success.','The loyal border states were among the jurisdictions outside its emancipation provisions.']);
q(s8,'Which development is most useful for explaining why this order became politically and militarily possible?','Enslaved people’s movement to Union lines combined with military needs and pressure to attack slavery.', ['The ending of armed resistance by every Confederate force before January 1863.','A consensus among northern voters that Black citizenship already included equal civil rights.','A Supreme Court ruling that the federal government lacked wartime authority over slavery.'],'Emancipation developed through actions from below and changing military and political circumstances.',['The war continued for years.','Racial equality remained heavily contested in the North.','The Proclamation asserted rather than followed such a denial of authority.']);
q(s8,'What is the strongest connection between the order’s military-service provision and subsequent citizenship claims?','Service provided evidence and political leverage for arguments that freedom should carry national rights.', ['Enlistment automatically resolved every state voting restriction before the war ended.','The provision replaced constitutional amendment as the only available route to abolition.','Black military participation primarily demonstrated acceptance of permanent exclusion from political life.'],'Military contributions strengthened claims that the nation owed protection and rights to its defenders.',['Service did not automatically confer universal suffrage.','The Thirteenth Amendment remained central to national abolition.','Service was frequently used to challenge exclusion rather than endorse it.']);
const industrialTable={type:'table',title:'Illustrative factory accounts: output, pay, and prices',columns:['Measure','Year A','Year B'],rows:[['Output units per worker','100','140'],['Weekly money wage','10','11'],['Cost of a fixed household basket','10','12']],note:'Entirely fictional model values created for analysis, not statistics from a historical factory or evidence of national trends. Assume identical basket contents and working hours. The exercise models debates in late-nineteenth-century industrialization.'};
const s9=set(6,'09',`Original illustrative model of factory accounts. Values are fictional and cannot establish what happened nationally. Under the stated assumptions, output per worker rises by 40%, money wages by 10%, and the cost of a fixed household basket by 20%. Use the relationship among measures, and distinguish what the model shows from conclusions needing independent historical evidence.`,industrialTable);
q(s9,'Under the stated assumptions, which conclusion is best supported by the table?','A worker’s money wage rose while purchasing power measured against this basket fell.', ['The wage increase kept pace with the stated rise in household costs.','The model shows declining output per worker alongside rising labor costs.','The increase in output establishes that the worker received a proportionate increase in pay.'],'The wage-to-basket ratio falls from 1 to 11/12 even though the money wage increases.',['Ten-percent wage growth is below twenty-percent basket-cost growth.','Output rises from 100 to 140, not downward.','The wage rises far less than output; productivity gains do not establish their distribution.']);
q(s9,'Which wider historical argument could the model illustrate but not independently prove?','Industrial growth could raise production without distributing gains proportionately to workers.', ['Railroad regulation necessarily reduced wages in the factory represented.','All late-nineteenth-century households experienced identical changes in consumption.','Political machines were the immediate cause of the modeled price increases.'],'The model distinguishes output growth from workers’ purchasing power, but actual historical prevalence needs evidence.',['No railroad policy is included.','A fictional factory cannot establish uniform household experience.','The model supplies no causal evidence about machines.']);
q(s9,'Which evidence would be most valuable for testing whether the modeled relationship characterized a particular industry?','Comparable wage, price, hours, and productivity records from representative firms over time.', ['A promotional image showing one unusually large factory building.','A business leader’s statement that competition rewards diligence.','The number of congressional speeches praising national prosperity.'],'Representative records would allow comparison of real wages and productivity under relevant conditions.',['Size does not measure wages, prices, or representativeness.','A principle asserted by a leader is not a measurement of outcomes.','Speech frequency measures rhetoric, not the economic relationship.']);
const s10=set(6,'10',`Primary-source instructional paraphrase, not a quotation: Dawes Act, 1887. The federal government may survey reservation land and allocate individual holdings under specified conditions. Land not allotted can become available through further arrangements for non-Indigenous acquisition. The legislation frames landholding through individual property and federal supervision rather than preservation of communal tenure and independent tribal control.\nPrimary text: ${links.dawes}`);
q(s10,'Which goal most directly underlies the policy’s organization of property?','Assimilating Indigenous people through individual agricultural landholding.', ['Preserving tribal governments’ unrestricted authority over communal territory.','Ending federal involvement in decisions about reservation land.','Replacing private farms throughout the United States with communal ownership.'],'Individual allotment reflected an assimilationist preference for private agriculture over tribal tenure.',['The policy weakened rather than guaranteed unrestricted communal control.','Federal supervision remained central.','Its direction was toward individual property, not national collectivization.']);
q(s10,'Which source would most directly test the difference between the statute’s protective language and its effects?','Records tracing the amount and control of Indigenous land before and after allotment.', ['A later textbook’s use of the word civilization without supporting records.','A map of railroad gauges without reservation boundaries.','A list of presidential election winners that omits land policy.'],'Ownership records can establish whether allotment preserved or transferred land.',['Repeating a value-laden label cannot establish outcomes.','Gauges alone do not show land transfers.','Election results without relevant policy evidence cannot test the effect.']);
q(s10,'Which comparison with earlier federal policy most accurately identifies continuity and change?','Removal and allotment both pressured Indigenous sovereignty, but one emphasized relocation and the other division of landholding.', ['Allotment restored the collective political autonomy that removal had curtailed.','Removal concerned Indigenous territory, while allotment concerned only European immigration.','Both policies used identical legal mechanisms and required no federal administration.'],'The shared pressure on sovereignty took different institutional forms.',['Allotment undermined collective control rather than simply restoring it.','Allotment directly targeted Indigenous reservation lands.','Different mechanisms and extensive federal involvement distinguish them.']);
const newDealTable={type:'table',title:'Selected New Deal institutional changes',columns:['Year','Policy','Mechanism summarized'],rows:[['1933','Federal deposit insurance','Protection for covered bank deposits'],['1935','National Labor Relations Act','Collective-bargaining rights for covered workers'],['1935','Social Security Act','Old-age insurance and other social protections']],note:'Original factual summary of selected policies, not an exhaustive policy list or statistical dataset. Coverage had important limits. Social Security primary text: '+links.socialSecurity};
const s11=set(7,'11',`Original secondary policy table: Selected New Deal institutional changes. The table records policy mechanisms, not a measurement of their success. Covered populations and implementation varied. Read the institutional pattern without assuming that every citizen or category of worker received the same protection. Social Security primary text: ${links.socialSecurity}`,newDealTable);
q(s11,'Which claim is most directly supported by the policies taken together?','Federal responsibility expanded beyond emergency aid to institutions intended to reduce recurring economic insecurity.', ['The administration sought to replace all private production with federal ownership.','Congress transferred primary responsibility for national labor standards to foreign governments.','The policies were designed chiefly to restrict the ability of covered workers to bargain collectively.'],'Insurance and bargaining institutions addressed continuing risks, not only immediate relief.',['The table does not show comprehensive nationalization.','These were national institutions, not a transfer abroad.','The labor law strengthened covered workers’ bargaining rights.']);
q(s11,'Which qualification most directly challenges a universal-benefit interpretation of the table?','Important categories of agricultural and domestic labor initially fell outside major protections.', ['The measures required institutions to administer the programs.','The laws were enacted in more than one congressional session.','Each program used a different statutory title.'],'Coverage exclusions made benefits unequal and had racial and gender consequences.',['Administration alone does not show who was excluded.','Timing differences do not establish unequal access.','Different titles are not evidence of distribution.']);
q(s11,'Which additional evidence would be most necessary to evaluate whether these laws ended the Depression?','Employment, output, and household-security trends together with evidence on wartime mobilization and other influences.', ['The existence of the statutes, treated as direct proof of their complete success.','A campaign poster describing the president as decisive.','The date on which each law first appeared in newspapers.'],'Evaluating outcomes requires economic evidence and other causes beyond legislative intent.',['Enactment establishes policy, not complete recovery.','A campaign claim reveals persuasion rather than measured effect.','News timing cannot establish economic recovery.']);
q(s11,'Which comparison with the late nineteenth century best captures a major shift without overstating it?','The federal state added social insurance and labor protections while continuing to sustain private enterprise.', ['Government stopped influencing business because social protections replaced economic policy.','The New Deal ended the relationship between public authority and private markets.','Earlier federal governments had lacked any involvement in transport, property, or labor disputes.'],'New responsibilities developed within a continuing market economy and an already active state.',['Public influence on business continued.','The policies changed that relationship rather than ending it.','Railroad support and strike intervention demonstrate earlier involvement.']);
const s12=set(7,'12',`Original secondary interpretation written for this form:\n\nDuring World War I, federal officials sought unity through propaganda, mobilization, and restrictions on certain dissent. Critics could face prosecution or social pressure for speech treated as obstruction of the war effort. These measures arose while officials publicly described the conflict as a defense of democracy. The tension was not simply between a government and a unified public: labor activists, immigrants, soldiers, employers, and reformers disagreed about loyalty, coercion, and legitimate political opposition.`);
q(s12,'Which evidence would most directly support the interpretation’s emphasis on a tension within democratic war aims?','A prosecution of a war critic paired with an official appeal to defend political liberty abroad.', ['An increase in military food purchases paired with a harvest report.','A troop transport schedule paired with a harbor map.','A comparison of army uniform costs in two supply districts.'],'The paired evidence juxtaposes proclaimed liberty with restricted dissent.',['Procurement and harvests do not directly establish the rights tension.','Transport logistics do not test treatment of opposition.','Uniform prices are not evidence of political liberty or prosecution.']);
q(s12,'Which comparison most carefully relates this setting to the Alien and Sedition Acts of 1798?','Both periods featured claims that external danger justified restrictions, though the political contexts and legal measures differed.', ['The same political party enacted identical statutes in both periods.','Both episodes eliminated debate about the legitimacy of dissent.','The earlier acts were enacted specifically to prepare for U.S. entry into World War I.'],'A recurring security-rights conflict can be analyzed without treating distinct episodes as identical.',['The parties and laws were not identical.','Restrictions provoked continuing constitutional opposition.','The 1798 laws belonged to a much earlier international crisis.']);
q(s12,'Which source would be especially useful for testing whether immigrant communities responded uniformly to wartime loyalty campaigns?','A range of community newspapers and personal accounts from different groups, compared across time.', ['One government poster assumed to represent every intended viewer’s reaction.','A national speech whose intended audience is treated as proof of actual agreement.','A census count of total population without information on political responses.'],'Varied community evidence can reveal disagreement concealed by a single official voice.',['Intended persuasion does not establish reception.','Audience and actual acceptance are different questions.','Population totals alone do not identify reactions.']);
const s13=set(7,'13',`Primary-source instructional paraphrase, not a quotation: Executive Order 8802, 1941. The president connects national defense to full participation and directs that defense-related employment not discriminate on specified grounds including race. The order provides a federal mechanism to receive and investigate complaints. It followed pressure from Black activists, including the threatened March on Washington associated with A. Philip Randolph.\nPrimary text and historical context: ${links.eo8802}`);
q(s13,'Which explanation best accounts for the connection between mobilization and the order?','Defense labor needs and organized pressure increased the cost of maintaining employment discrimination.', ['Defense preparation reduced the federal government’s involvement in industrial production.','The order resulted from a prior national consensus that employment discrimination had disappeared.','The order chiefly responded to the complete demobilization of the wartime economy.'],'Mobilization and activism made exclusion both a practical and political issue.',['Defense preparation expanded federal-industrial coordination.','The order addressed continuing discrimination.','The order came during preparation for expanded war production, not demobilization.']);
q(s13,'Which evidence would most directly qualify a claim that the order guaranteed equal wartime experience?','Continued discrimination in other institutions and the incarceration of Japanese Americans.', ['The government’s creation of a complaint mechanism.','The order’s explicit statement of a nondiscrimination principle.','The increased demand for industrial labor.'],'Unequal treatment elsewhere shows why a targeted order did not establish universal equality.',['A mechanism indicates an enforcement effort rather than its complete reach.','A principle alone does not establish implementation or wider equality.','Labor demand does not prove equal treatment.']);
q(s13,'Which interpretation best recognizes activist agency without ignoring executive authority?','Federal action emerged through the interaction of presidential power with organized demands from outside government.', ['The president’s signature makes prior collective pressure irrelevant to causation.','The threatened march itself legally amended every defense contract without federal action.','The order proves that grassroots action mattered only after all legal protections were already secure.'],'Policy can depend on both institutional authority and pressure that changes its use.',['A signature does not explain why a decision was made.','Activism exerted pressure but did not itself perform every legal act.','The pressure arose because protections were not secure.']);
const s14=set(8,'14',`Primary-source instructional paraphrase, not a quotation: President Harry Truman's message to Congress, March 1947. Truman requests economic and military assistance for Greece and Turkey and frames aid as support for peoples resisting coercion from armed minorities or outside pressure. The speech seeks congressional approval and presents local crises as part of a broader contest over political freedom and national security.\nPrimary text: ${links.truman}`);
q(s14,'How does the speech’s audience help explain its framing of the requested aid?','A broad security argument could persuade legislators that a regional crisis warranted national resources.', ['Congressional listeners already possessed independent authority to impose policy without approving funds.','The speech was chiefly a private report intended to avoid public debate about commitments.','The president was negotiating surrender terms directly with Soviet military commanders.'],'Truman needed congressional support for resources and policy, giving the broad framing a persuasive function.',['The request sought legislative authorization and resources, not a bypass of their role.','It was a public message to Congress rather than a private report.','The audience and purpose were not negotiations with Soviet commanders.']);
q(s14,'Which development provides the closest policy parallel to the speech’s use of assistance?','The Marshall Plan’s use of recovery aid to strengthen political and economic ties in Europe.', ['The decision to avoid U.S. involvement in any collective-defense alliance.','The transfer of all European reconstruction responsibility to individual U.S. charities.','The immediate demobilization of federal foreign-policy institutions after World War II.'],'Both aid programs connected economic conditions to the emerging containment strategy.',['The U.S. joined NATO rather than rejecting every alliance.','Recovery involved a major governmental program.','The national security state expanded rather than disappeared.']);
q(s14,'Which limitation should a historian recognize when using the speech to explain Greek and Turkish politics?','A U.S. justification cannot alone establish the motives or goals of all local actors.', ['Its public delivery makes the message useless as evidence of U.S. aims.','Its official status proves that local conflicts had no causes beyond Soviet direction.','Its description of freedom establishes the equal treatment of every group within the aid recipients.'],'The speech reveals U.S. framing, while local dynamics require additional evidence.',['Public persuasion is itself evidence of aims and strategy.','Official claims do not erase civil, regional, or nationalist causes.','A declared principle is not proof of recipients’ practices.']);
q(s14,'Which later development most clearly demonstrates the potential expansion of the framework expressed here?','U.S. leaders interpreted conflicts in regions beyond Europe through the objective of containment.', ['The United States abandoned attention to communism after the aid request passed.','Every decolonizing nation accepted the same U.S. definition of its political interests.','Presidents ceased using national-security arguments to justify overseas commitments.'],'Containment became a framework for later involvement in Asia and elsewhere.',['Anticommunism remained central to policy.','New states pursued diverse priorities and often resisted superpower framing.','The security justification persisted and expanded.']);
const housingTable={type:'table',title:'Fictional lending model: equal finances, unequal access',columns:['Applicant group','Financially qualifying applications','Loans approved'],rows:[['Group X','50','40'],['Group Y','50','10']],note:'Original hypothetical model, not data from an actual lender, city, or census. Financial qualifications are assumed identical; the model stipulates an exclusionary rule that disadvantages Group Y. No national rate or racial statistic can be inferred from these figures.'};
const s15=set(8,'15',`Original hypothetical lending model for analyzing postwar housing inequality. The two groups submit equal numbers of financially qualifying applications, but the stipulated exclusionary rule disadvantages Group Y. The figures are invented; they do not identify an actual racial group or quantify national discrimination. They illustrate a possible mechanism through which access to credit could shape opportunities for ownership and later wealth.`,housingTable);
q(s15,'Which inference follows from the model without extending it beyond its stated evidence?','Under these conditions, a qualifying Group X applicant was four times as likely to receive a loan as a qualifying Group Y applicant.', ['The national mortgage market had an approval rate equal to Group X’s rate.','The two groups’ incomes must have differed enough to explain the approval gap.','The model establishes the lifetime wealth of every person whose application was approved.'],'Approval rates are 40/50 and 10/50; their ratio is four within this model.',['The model cannot establish a national rate.','Equal financial qualifications are an explicit assumption.','Approval is not a complete record of later wealth or financial risk.']);
q(s15,'Which mechanism best connects the modeled access gap to a historical argument about postwar inequality?','Unequal entry to ownership could limit opportunities to accumulate housing equity over time.', ['A denied mortgage necessarily reduced the national supply of all forms of housing.','Approval guaranteed identical property appreciation for every borrowing household.','Housing credit influenced only immediate consumption and had no connection to future resources.'],'Access to an appreciating asset can affect later wealth, though actual outcomes vary.',['One denial does not establish national supply effects.','Location, prices, debt, and other conditions affect returns.','Ownership can influence equity and intergenerational resources.']);
q(s15,'What evidence would be most necessary before using the model to make a claim about a particular historical city?','Actual lending rules, applicant records, and housing-market conditions from that city.', ['A larger fictional sample generated using the same stipulated exclusion.','A national political slogan praising homeownership without implementation records.','The fact that both groups in the model contain the same number of applications.'],'Empirical records are needed to establish whether the proposed mechanism operated there.',['More invented cases do not become historical observations.','A slogan shows values or persuasion, not the city’s practices.','A model assumption is not evidence about a real city.']);
const s16=set(8,'16',`Original secondary interpretation written for this form:\n\nThe civil rights movement changed national law partly by making ordinary local exclusion a question of federal responsibility. Litigation challenged doctrine; boycotts, sit-ins, voter registration, and marches exposed practices that formal legal promises had failed to change. Campaigns did not operate through a single strategy or a single leader. Legal victories altered opportunities, while violence, unequal resources, and disputes about enforcement kept the meaning of equality contested. Other rights movements drew lessons from these campaigns but also pursued goals rooted in their own histories and institutions.`);
q(s16,'Which pair of developments would best support the distinction between challenging doctrine and exposing implementation?','Brown v. Board of Education and direct-action campaigns confronting continued segregation.', ['Two campaign biographies that omit organizations and local participants.','A national election result and a list of television manufacturers.','Two court decisions treated as proof that social conditions changed immediately.'],'A ruling addresses constitutional doctrine, while direct action can reveal resistance and daily exclusion.',['Biographies without movement evidence cannot establish the two mechanisms.','These records do not directly show the stated distinction.','Treating rulings as immediate outcomes ignores the implementation issue.']);
q(s16,'Which additional evidence would most directly challenge a single-leader explanation of the movement?','Local organization records documenting sustained work by students, churches, and registration volunteers.', ['A photograph concentrating attention on one nationally prominent speaker.','A speech in which an official describes a personal decision without mentioning pressure.','A list of dates that records only the signing of federal statutes.'],'Organizational records can reveal distributed agency and work not captured by prominent speeches.',['A focused image may conceal broader participation.','An official’s omission is not proof that pressure was absent.','Signing dates do not explain the organizing that preceded legislation.']);
q(s16,'Which comparison best respects both influence and difference among rights movements?','Indigenous activists could use protest tactics while demanding treaty enforcement and tribal sovereignty distinct from assimilation.', ['Shared use of demonstrations proves that all movements sought identical legal outcomes.','Tribal sovereignty claims required Indigenous activists to reject every form of U.S. citizenship.','Women’s and gay rights campaigns had no connection to wider debates over equality because their targets differed.'],'Methods can circulate while collective sovereignty remains a distinct political objective.',['Tactical similarity does not establish identical goals.','Citizenship and tribal membership could coexist.','Distinct targets do not erase shared arguments or influences.']);
const s17=set(9,'17',`Original secondary interpretation written for this form:\n\nAfter 1980, trade integration and digital coordination allowed many firms to reorganize production across borders. Consumers, owners, workers, and communities did not necessarily experience the same gains or losses. Factory closures could coincide with lower prices and expanding service or technology sectors. Political responses therefore concerned distribution and authority as well as total output: who could influence investment, what protections government should provide, and how national identity should be defined in a changing society. None of these questions began in 1980, although institutions and technologies altered their form.`);
q(s17,'Which evidence would most directly support the passage’s distributional interpretation?','Records showing lower consumer prices alongside concentrated employment losses in a particular manufacturing region.', ['A national output total treated as a complete account of every household’s experience.','A company announcement assumed to describe all workers’ preferences accurately.','A survey asking only whether respondents recognize a product’s brand name.'],'The combined records can show benefits and costs falling on different populations.',['Aggregate output cannot establish distribution.','A company’s position does not automatically represent workers.','Brand recognition does not measure the relevant outcomes.']);
q(s17,'Which comparison with the late nineteenth century best develops the passage’s continuity-and-change claim?','Both periods raised concerns about concentrated economic power, while digital networks changed the scale and organization of coordination.', ['Earlier industrialization involved no government action, whereas later production was entirely state-owned.','Worker insecurity began only with the appearance of the internet.','The development of global production removed disputes over immigration and national belonging.'],'A recurring power question can coexist with technological and institutional changes.',['Both periods involved mixed public and private roles; later production was not entirely state-owned.','Earlier workers also faced insecurity and unequal bargaining power.','Global integration generated continuing debates about belonging.']);
q(s17,'Which research design would best test the claim that a specific trade policy caused local job losses?','Compare exposed and less-exposed industries over time while considering automation, demand, and prior regional trends.', ['Treat the policy’s enactment date as sufficient proof of every later closure’s cause.','Compare two unrelated national elections without examining employment or industry data.','Use one worker’s experience to establish a uniform outcome for the entire country.'],'Causal assessment needs relevant comparisons and competing explanations, not sequence alone.',['Temporal succession is not sufficient causal evidence.','Election results alone do not test the employment mechanism.','Individual testimony is valuable but not automatically nationally representative.']);
const criterion=(key:string,label:string,points:number,prompt:string,guidance:string)=>({key,label,points,prompt,guidance});
function frq(id:string,unit:number,title:string,frqType:string,question:string,criteria:any[],explanation:string,extra:any={}){return{id:`apush-exam-${id}`,domain:domain(unit),difficulty:'Hard',format:'frq',title,frqType,question,criteria,maxPoints:criteria.reduce((n,c)=>n+c.points,0),rubric:criteria.map(c=>`${c.label} — ${c.points} point${c.points===1?'':'s'}: ${c.guidance}`).join('\n\n'),explanation:`Original unofficial practice. Feedback applies the stated instructional criteria and does not establish an official AP score. ${explanation}`,...extra};}
const secondarySaq=`Source: Two original secondary interpretations written by AscendSAT for this form. They are instructional analyses, not quotations attributed to published historians.\n\nInterpretation A: Distinct colonial environments and settlement patterns encouraged differences in household organization, local production, and institutions. A tobacco-exporting Chesapeake plantation and a New England family farm did not organize land and labor in the same way.\n\nInterpretation B: Regional contrasts can conceal commercial connections. Ships, credit, provisions, and export demand linked colonies to one another and to Caribbean plantations; a region without the same concentration of plantations could still profit from enslaved production.\n\nAnswer ALL parts using developments in British North America between 1607 and 1754.\nA. Describe ONE difference in emphasis between A and B.\nB. Explain ONE specific piece of historical evidence supporting A's interpretation.\nC. Explain ONE specific piece of historical evidence supporting B's interpretation.`;
const monroeSaq=`Source: James Monroe, annual message to Congress, December 1823. The following is an original instructional paraphrase of a primary text, not a quotation. Monroe warns against further European colonization and intervention in the Americas while distinguishing existing colonies and European internal affairs. He frames European extension of political control as a danger to U.S. peace and safety. Source: ${links.monroe}\n\nAnswer ALL parts.\nA. Identify ONE foreign-policy objective expressed in the source.\nB. Explain ONE development between 1800 and 1823 that helps account for the statement.\nC. Explain ONE reason the statement alone does not prove the United States could fully enforce that objective throughout the hemisphere in 1823.`;
const rightsTable={type:'table',title:'Selected federal actions concerning racial discrimination, 1954–1965',columns:['Year','Institution','Action summarized'],rows:[['1954','Supreme Court','Brown rejects racial segregation in public schools'],['1964','Congress and president','Civil Rights Act prohibits major forms of discrimination in covered settings'],['1965','Congress and president','Voting Rights Act strengthens protection against racial voting discrimination']],note:'Original secondary timeline compiled from actual federal actions; not a count of rights violations or a measure of enforcement. Sources: National Archives civil-rights and voting-rights primary documents, and Brown decision resources.'};
const timelineSaq=`Source: Original secondary timeline summarizing selected federal actions, 1954–1965. It is not an official exam graphic. Read the table; the entries identify legal changes rather than their complete implementation.\n\n1954 | Supreme Court | Brown rejects racial segregation in public schools.\n1964 | Congress and president | Civil Rights Act prohibits major forms of discrimination in covered settings.\n1965 | Congress and president | Voting Rights Act strengthens protection against racial voting discrimination.\n\nPrimary-document references: ${links.civilRights} and ${links.votingRights}. Brown historical document resource: https://www.archives.gov/milestone-documents/brown-v-board-of-education\n\nAnswer ALL parts using the period 1945–1980.\nA. Describe ONE pattern in the federal actions shown in the timeline.\nB. Explain ONE movement strategy that helped bring about a change shown in the timeline.\nC. Explain ONE reason the timeline cannot establish that racial inequality had ended by 1980.`;
const saq=[
frq('saq-1',2,'Short answer 1: Regional contrasts and Atlantic connections','source_analysis',secondarySaq,[
 criterion('A','Part A',1,'Describe the difference in emphasis.','Award 1 for distinguishing A’s focus on regional social/economic differences from B’s focus on interregional connections. Do not accept the claim that A denies all trade or B claims all labor systems were identical.'),
 criterion('B','Part B',1,'Explain evidence supporting A.','Award 1 for a specific example connected to regional organization, such as Chesapeake tobacco estates and labor demand versus New England mixed farms, family settlement, or towns. A label such as geography without a specific connection earns 0.'),
 criterion('C','Part C',1,'Explain evidence supporting B.','Award 1 for explaining an actual connection, such as northern shipping or provisions sold to Caribbean plantations, or colonial trade and credit tied to slave-produced commodities. Evidence must show the relationship, not merely name two regions.')],
 'The interpretations can both be supported. Evaluate each requested explanation independently; an answer need not choose one interpretation as exclusively correct.',{sourceType:'secondary_text',passage:secondarySaq,stimulusId:'apush-exam-saq-secondary'}),
frq('saq-2',4,'Short answer 2: A hemispheric policy claim','source_analysis',monroeSaq,[
 criterion('A','Part A',1,'Identify one objective.','Award 1 for opposing new European colonization or intervention in the Americas, or seeking protection of U.S. security against renewed European control. A claim that Monroe announced annexation of all Latin America earns 0.'),
 criterion('B','Part B',1,'Explain relevant context.','Award 1 for linking Latin American independence movements, concern about European restoration, or a relevant development in U.S. hemispheric relations to the warning. The example must precede or be contemporaneous with 1823.'),
 criterion('C','Part C',1,'Explain a limit to inference about enforcement.','Award 1 for explaining that a presidential declaration establishes an asserted policy, while military/naval resources, diplomacy, or other states’ reactions determine enforcement. An accurate reference to limited U.S. power or Britain’s independent interests must be connected to this distinction.')],
 'Distinguish Monroe’s declared aim from later interventionist adaptations. Do not require a student to claim that every Latin American state supported U.S. leadership.',{sourceType:'primary_text',passage:monroeSaq,stimulusId:'apush-exam-saq-primary'}),
frq('saq-3',8,'Short answer 3: Federal action and implementation','source_analysis',timelineSaq,[
 criterion('A','Part A',1,'Describe a pattern shown by the timeline.','Award 1 for an accurate pattern such as multiple branches taking action against distinct forms of racial discrimination, or expansion from a school ruling to broader legislative protections. Merely copying a year earns 0.'),
 criterion('B','Part B',1,'Explain a contributing movement strategy.','Award 1 for connecting a specific strategy to a listed change: NAACP litigation and Brown; direct action and pressure for the 1964 law; or voter registration/Selma mobilization and the 1965 law. Naming a strategy without explaining influence earns 0.'),
 criterion('C','Part C',1,'Explain the timeline’s limit as evidence.','Award 1 for explaining that enactments do not measure enforcement or all inequalities, supported by an example such as residential segregation, unequal resources, resistance, or discriminatory practices. Do not award a point merely for saying the table is incomplete without explaining why that matters.')],
 'A table of institutions and legal acts can support an argument about formal change while leaving actual conditions and enforcement to be investigated. This non-text source concerns a different period from the other two SAQs.',{sourceType:'non_text',passage:timelineSaq,stimulusId:'apush-exam-saq-timeline',stimulus:rightsTable})
];
const documents=[
{id:'D1',title:'Thirteenth Amendment',author:'U.S. Congress and ratifying states',date:'1865',url:links.amendments,text:'Instructional paraphrase, not a quotation: The amendment bars slavery and involuntary servitude in the United States and places under its jurisdiction, except as punishment following conviction for crime. It also gives Congress authority to enforce the prohibition through legislation. This establishes a national constitutional rule, not a complete definition of economic or political equality.'},
{id:'D2',title:'Fourteenth Amendment, Section 1',author:'U.S. Congress and ratifying states',date:'1868',url:links.amendments,text:'Instructional paraphrase, not a quotation: People born or naturalized in the United States and subject to its jurisdiction hold national and state citizenship. States may not deny the specified protections of citizenship, deprive persons of life, liberty, or property without due process, or deny equal protection. The provision changes constitutional limits on states; enforcement remains a separate historical question.'},
{id:'D3',title:'Southern Horrors: Lynch Law in All Its Phases',author:'Ida B. Wells',date:'1892',url:links.wells,text:'Instructional paraphrase of Wells’s argument, not a quotation: Claims used to excuse lynching concealed racial terror rather than providing a legitimate system of justice. Wells challenges the accounts offered by defenders of mob violence and calls attention to authorities’ failure to protect Black lives. Her investigation also points to collective action and economic pressure as means of resistance. The pamphlet’s argument should be distinguished from the justifications it criticizes.'},
{id:'D4',title:'Plessy v. Ferguson, majority opinion',author:'Justice Henry Billings Brown for the U.S. Supreme Court majority',date:'1896',url:links.plessy,text:'Instructional paraphrase, not a quotation: The majority upholds Louisiana’s requirement for separate railroad accommodations, treating compulsory racial separation as compatible with legal equality under its reading of the Fourteenth Amendment. It distinguishes what it describes as legal or political equality from social relations. This summary reports the majority’s reasoning and does not endorse the reasoning or imply accommodations were equal in practice.'},
{id:'D5',title:'Executive Order 8802',author:'President Franklin D. Roosevelt',date:'1941',url:links.eo8802,text:'Instructional paraphrase, not a quotation: Exclusion from defense work on grounds including race harms participation and national unity. The order directs nondiscrimination in defense-related employment and establishes a mechanism to investigate complaints. Its defense-production purpose and limited institutional scope matter: the text should not be mistaken for a general abolition of every discriminatory practice.'},
{id:'D6',title:'Executive Order 9066',author:'President Franklin D. Roosevelt',date:'1942',url:links.eo9066,text:'Instructional paraphrase, not a quotation: Citing wartime military needs, the president authorizes military areas from which persons may be excluded and provides for federal support of the resulting measures. The order does not name Japanese Americans in its wording. Its implementation led to their mass forced removal and incarceration, including citizens, demonstrating why both the document’s stated authority and its administration must be examined.'},
{id:'D7',title:'Speech to Congress on voting rights',author:'President Lyndon B. Johnson',date:'March 15, 1965',url:links.johnson,text:'Instructional paraphrase, not a quotation: Johnson presents denial of the vote as a national constitutional and moral problem rather than only a regional dispute. He calls for congressional action to protect voting and frames federal intervention as necessary to make citizenship meaningful. The speech’s persuasive purpose is to win legislation; it is not by itself evidence that every voting barrier has already disappeared.'}
];
const dbqQuestion=`Evaluate the extent to which federal action changed the relationship between legal freedom and the practical exercise of equal rights in the United States from 1865 to 1965.\n\nDevelop a position, explain relevant context, and use the SEVEN documents together with specific outside evidence. Analyze why sources’ situations, purposes, audiences, or viewpoints matter to your argument. You may identify changes, continuities, unequal effects, and important contradictions.\n\nThese are condensed instructional paraphrases of real primary sources, not quotations or released exam material. Source titles, authors, dates, and links are supplied. Do not treat legal declarations or public justifications as proof of complete implementation.\n\n${documents.map((d,i)=>`Document ${i+1}: ${d.title}\n${d.author}, ${d.date}\n${d.text}\nPrimary source: ${d.url}`).join('\n\n')}`;
const dbq=frq('dbq-1',8,'Document-based question: Freedom, equality, and federal power','document_based',dbqQuestion,[
 criterion('thesis','Position',1,'State an arguable answer to the question.','Award 1 for a defensible position with a reasoning path, not a restatement. A response may stress change, limits, or contradictions.'),
 criterion('context','Setting',1,'Connect the issue to a wider historical development.','Award 1 for a developed relevant setting, such as emancipation and Reconstruction, rather than a name or date alone.'),
 criterion('documents','Document evidence',2,'Interpret documents and use them in the argument.','Award 1 for relevant, accurate treatment of at least three documents; award 2 when at least four support the argument. Quotation or document-number lists alone earn 0.'),
 criterion('outside','Additional evidence',1,'Use specific evidence not supplied in the documents.','Award 1 for a distinct accurate example advancing the argument, not the same evidence credited for context. Possible examples include enforcement acts, Brown, the NAACP, or Selma organizing; alternatives are welcome.'),
 criterion('sourcing','Source analysis',1,'Explain why sourcing affects interpretation.','Award 1 for explaining a relevant sourcing feature for at least two documents. Merely naming an author, date, or bias earns 0.'),
 criterion('complexity','Complex understanding',1,'Develop qualification or relationships using evidence.','Award 1 for sustained complexity: for example, explaining how one federal state could expand protection while restricting another population’s rights. Equivalent developed analysis qualifies; a token qualification does not.')],
 'One defensible line of reasoning traces constitutional freedom and later enforcement while showing that judicial doctrine, violence, and wartime coercion restricted practical equality. Other arguments can earn full credit. A strong essay must not attribute Wells’s opponents’ claims to Wells or confuse EO 9066’s wording with its effects.',{documents,passage:'Seven primary-source paraphrases appear in the question.',stimulusId:'apush-exam-dbq-documents'});
const leqQuestion=`Economic development and territorial expansion repeatedly altered who could participate in American public life. From the founding era through Reconstruction, these changes could widen opportunity while creating or reinforcing exclusions.\n\nDevelop an argument evaluating how economic OR territorial change affected political participation in the United States between 1783 and 1877. You may focus on ONE or MORE developments and are not expected to address the entire period. Your choice is within this single required prompt, not among separate optional essays.\n\nPresent an arguable position, provide relevant context, support your argument with at least TWO specific pieces of historical evidence, and explain relationships through historical reasoning. Develop a qualification, competing perspective, or other evidence-based complexity where appropriate.`;
const leq=frq('leq-1',4,'Long essay: Development and political participation','long_essay',leqQuestion,[
 criterion('thesis','Position',1,'Make a defensible claim addressing the prompt.','Award 1 for an argument with a reasoning path. A list of developments or a repeated prompt earns 0.'),
 criterion('context','Setting',1,'Explain a relevant broader setting.','Award 1 for developed context tied to the chosen change, not an isolated reference.'),
 criterion('evidence','Evidence',2,'Provide and use at least two specific examples.','Award 1 for two relevant accurate examples; award 2 when two support the argument. Possible evidence includes suffrage rules, party mobilization, removal, territorial slavery conflict, or Reconstruction participation.'),
 criterion('reasoning','Relationships',1,'Explain a causal, comparative, or continuity-and-change relationship.','Award 1 for organizing an explanation around a meaningful relationship rather than chronology alone.'),
 criterion('complexity','Complex understanding',1,'Develop an evidence-based qualification or layered explanation.','Award 1 for sustained treatment of differing effects, interacting causes, or a supported counterargument. A passing however or unsupported assertion earns 0.')],
 'The response may focus narrowly within the date range. For example, it could connect expansion of white male participation to Indigenous dispossession, or examine how territorial slavery conflict changed political coalitions and eventually citizenship. Do not require the essay to cover every decade or both economic and territorial change.');
