export const APUSH_EXAM={id:'apush-form-1',courseId:'ap-us-history',title:'Practice exam 1',mcq,saq,writing:[dbq,leq],references,notes:'Original unofficial form organized for May 2027 practice: 55 MCQs in 17 shared-stimulus sets; three required SAQs using secondary text, primary text, and a non-text source in different periods; one seven-document DBQ; one broad required LEQ with choice within its scope. Tables labeled fictional are illustrative models, not historical statistics; the policy tables summarize actual acts. The map is schematic and not to scale. Secondary interpretations are original instructional writing, not invented historian quotations. Primary-source paraphrases are condensed and linked; their reading load differs from unabridged archival texts. Difficulty labels are internal instructional judgments, not official calibration. Rubric-guided feedback and any practice score are not guarantees of an official AP result.'};
